package com.example.orchestrator;
import java.nio.charset.StandardCharsets; import java.security.MessageDigest; import java.time.Instant; import java.util.*;
public class AuditLog {private final List<Entry> entries=new ArrayList<>();private String previous="GENESIS";public synchronized void append(String run,String node,String event,String details){String payload=run+"|"+node+"|"+event+"|"+details+"|"+Instant.now()+"|"+previous;String hash=sha(payload);entries.add(new Entry(run,node,event,details,previous,hash));previous=hash;}public boolean verify(){String prev="GENESIS";for(Entry e:entries){if(!e.previousHash.equals(prev))return false;prev=e.hash;}return true;}private static String sha(String s){try{return HexFormat.of().formatHex(MessageDigest.getInstance("SHA-256").digest(s.getBytes(StandardCharsets.UTF_8)));}catch(Exception e){throw new IllegalStateException(e);}}public record Entry(String runId,String nodeId,String event,String details,String previousHash,String hash){}}
